function tileSuo(n){
  if (n === 1) return tileBody() + BIRD_ART;
  const { prim, P } = caneSetup(n);
  return tileBody() + renderSpec(BAMBOO_SPECS[n], prim, caneBeads, P, caneSlit) + overlayFor(BAMBOO_SPECS[n], prim);
}

// ═══════════════════ bonus tiles: flowers 花 & seasons 季 (baked v1) ═══════════════════
// The eight bonus tiles as frozen out of the design of record,
// mjrc-admin/art/claude-design-mj/flower-v1-lab.html, by that folder's
// tools/bake-flowers.mjs. Re-run it with --consumers to update the block below;
// it rewrites everything between the BAKED-V1 markers. Do not hand-edit.
//
// Each entry is one tile's INNER markup at the composition its lab row picks
// (梅蘭竹菊 W3, 春 W3, 夏 W5, 秋 W3, 冬 W3), without the tileBody() rect:
//
//   <g class="bonus-motif" transform="translate(10 24) scale(0.8)">…</g>  the motif,
//       authored full-canvas and placed by the lab's own LAYOUT.motif
//   <text class="fidx" …>n</text>                                   the index
//   <g class="glyph">…</g>                                          the name
//
// The index and the name are therefore ALREADY painted on top of the motif,
// which is the whole job the old bonusTile() re-split did — so that re-split is
// gone rather than kept: its translate(17 22) scale(0.78) would be a second,
// wrong transform on a motif the lab has already positioned. `.fidx` and
// `.glyph` survive as the CSS optical-size hooks (flower-size-lab.html drives
// both), and the <text> inside g.glyph is un-recentred exactly as before, so
// recenterGlyphs() still has its job.
