const FLOWER_TILES = [0, 1, 2, 3].map(i => [BONUS_LABELS[i], () => bonusTile(i)]);
const SEASON_TILES = [4, 5, 6, 7].map(i => [BONUS_LABELS[i], () => bonusTile(i)]);
